schema_json:
{
  "$defs": {
    "CandidateOrder": {
      "enum": [
        "alphabetical",
        "by_number",
        "by_party",
        "by_listed",
        "rotated",
        "random",
        "unclear",
        "not_applicable"
      ],
      "title": "CandidateOrder",
      "type": "string"
    },
    "QuestionType": {
      "enum": [
        "estimulada",
        "espontanea",
        "avaliacao",
        "rejeicao",
        "party",
        "demographic",
        "issue",
        "screener",
        "other",
        "unclear"
      ],
      "title": "QuestionType",
      "type": "string"
    },
    "QuestionnaireScenario": {
      "description": "One question block from the questionnaire PDF, in filing order.\n\nThis models EVERY block in the instrument — not only vote-intention\nscenarios but also approval/rejection, party-preference, issue,\nscreener and demographic blocks — so the downstream analysis can\nreconstruct question ordering and priming structure (e.g. an approval\nor rejection item placed BEFORE the first estimulada). The order and\n`position` of blocks is load-bearing; never reorder them.",
      "properties": {
        "position": {
          "description": "1-based filing order of this block in the instrument (1 = first question printed). MUST reflect the true printed order; this is what lets the analysis test whether an approval/rejection item precedes the first estimulada.",
          "title": "Position",
          "type": "integer"
        },
        "label": {
          "description": "The exact label or number used in the PDF, verbatim. E.g. 'P5', 'ESTIMULADA 1', 'ESPONTÂNEA', 'CENÁRIO A — COM CANDIDATO X'. If unlabeled, use 'unlabeled_<N>'.",
          "title": "Label",
          "type": "string"
        },
        "question_type": {
          "$ref": "#/$defs/QuestionType",
          "description": "Classification per the QuestionType enum."
        },
        "question_text": {
          "default": "",
          "description": "1-2 sentences of the question prompt as written, verbatim Portuguese. Up to ~300 chars. If the question is mainly a candidate list with a stem like 'Se a eleição fosse hoje, em quem o(a) Sr.(a) votaria?', include the stem here.",
          "title": "Question Text",
          "type": "string"
        },
        "candidates_listed": {
          "description": "VOTE-INTENTION ROSTER ONLY: candidate / option names as listed in the PDF, in the order they appear. Up to 15 entries. Preserve original capitalization. Populate for `estimulada` scenarios (the closed list shown to the respondent). Leave empty for every other question_type — use `subject_candidates` to record who an approval / rejection / issue question is ABOUT.",
          "items": {
            "type": "string"
          },
          "title": "Candidates Listed",
          "type": "array"
        },
        "subject_candidates": {
          "description": "WHO THIS QUESTION IS ABOUT, when it targets specific candidate(s) but is NOT a vote-intention roster. Populate for `avaliacao` (the candidate(s) being rated), `rejeicao` (the candidate(s) named in a 'nunca votaria em X' item, if named rather than open), and `issue` items that name a candidate. Verbatim names, preserve capitalization. Empty for estimulada/espontanea (use candidates_listed), party, demographic and screener blocks. This is the primitive that lets the analysis match the item against the sponsor / the sponsor's opponent — do NOT judge sponsorship here, just record the names the PDF states.",
          "items": {
            "type": "string"
          },
          "title": "Subject Candidates",
          "type": "array"
        },
        "candidate_order": {
          "$ref": "#/$defs/CandidateOrder",
          "description": "How the candidate list is ordered. 'rotated' or 'random' only when the PDF explicitly instructs the interviewer to rotate / randomize. 'by_listed' for any printed order with no stated rule. 'not_applicable' for non-vote-intention questions."
        }
      },
      "required": [
        "position",
        "label",
        "question_type",
        "candidate_order"
      ],
      "title": "QuestionnaireScenario",
      "type": "object"
    }
  },
  "description": "Survey-instrument extraction from `questionario_pesquisa` PDF.\n\nThe core output is `scenarios`: the COMPLETE, ORDERED transcript of\nevery question block in the instrument (vote-intention, approval,\nrejection, party, issue, screener, demographic), in true filing\norder. Presence flags, counts, and priming diagnostics are NOT\nextracted as separate judgments — they are derived downstream from\nthis ordered transcript crossed with sponsor identity. In\nparticular, Fernando's priming hypothesis (an approval item about\nthe sponsor's candidate, or a rejection item about an opponent,\nplaced BEFORE the first estimulada) is a predicate over\n`position` + `question_type` + `subject_candidates`, computed in the\nPanel-B analysis — not here.",
  "properties": {
    "pesquisa_realized": {
      "description": "True normally. False ONLY when the PDF is a 'PESQUISA NÃO REALIZADA' stamp. When false, all other fields default to empty / unclear.",
      "title": "Pesquisa Realized",
      "type": "boolean"
    },
    "scenarios": {
      "description": "The COMPLETE instrument transcript: EVERY question block, in true printed (filing) order, each with its 1-based `position`. Include vote-intention (estimulada/espontanea), approval (avaliacao), rejection (rejeicao), party, issue, screener AND demographic blocks — do NOT drop or reorder any. NEVER reorder to group by type: the order is the signal. Verbosity is tiered to stay within budget: for estimulada/avaliacao/rejeicao/party blocks give full question_text + candidates_listed / subject_candidates; for demographic/screener/issue blocks a one-line question_text (or just the label) is enough — but still list them in position order. HARD CAP 30 blocks: if the instrument is longer, keep the first 30 IN ORDER (never skip ahead) and set scenarios_truncated=true. Do NOT count or total the scenarios — downstream derives counts/positions from this list.",
      "items": {
        "$ref": "#/$defs/QuestionnaireScenario"
      },
      "title": "Scenarios",
      "type": "array"
    },
    "scenarios_truncated": {
      "default": false,
      "description": "True ONLY if the instrument has MORE question blocks than the (cap-30) ones returned. False normally. A yes/no observation, not a count — downstream derives the vote-intention count, first-estimulada position and headline label from the scenarios transcript (count of estimulada+espontanea; min position where type==estimulada; its label).",
      "title": "Scenarios Truncated",
      "type": "boolean"
    },
    "name_rotation_documented": {
      "default": false,
      "description": "True if the PDF anywhere documents an instruction to rotate / alternate / randomize candidate name order across respondents (e.g. 'inverter ordem dos nomes', 'rotacionar', 'alternar a cada entrevista'). False for fixed-order printed rosters.",
      "title": "Name Rotation Documented",
      "type": "boolean"
    },
    "name_rotation_evidence": {
      "default": "",
      "description": "Verbatim quote or close paraphrase, 1-2 sentences, of the rotation instruction. Empty when name_rotation_documented is False.",
      "title": "Name Rotation Evidence",
      "type": "string"
    },
    "nonresponse_instruction_present": {
      "default": false,
      "description": "True if the questionnaire contains any printed instruction about handling undecided / refusal / blank / null responses (e.g. 'NÃO LER ESTAS OPÇÕES', 'redistribuir indecisos proporcionalmente', 'descartar brancos'). False otherwise.",
      "title": "Nonresponse Instruction Present",
      "type": "boolean"
    },
    "nonresponse_instruction_text": {
      "default": "",
      "description": "Verbatim or paraphrased text of the nonresponse instruction, up to ~400 chars Portuguese. Empty when nonresponse_instruction_present is False.",
      "title": "Nonresponse Instruction Text",
      "type": "string"
    },
    "extraction_notes": {
      "default": "",
      "description": "Free-form notes on PDF format anomalies, OCR concerns, or schema fits poorly (e.g. instrument is a different language, the PDF is a relatório attached by mistake). Empty when the extraction is clean.",
      "title": "Extraction Notes",
      "type": "string"
    }
  },
  "required": [
    "pesquisa_realized"
  ],
  "title": "PollQuestionario",
  "type": "object"
}
